    for (center_r, c, color) in found_blocks:
        for nr in range(rows):
            if nr == center_r:
                continue
            output[nr][c] = color

    # Set self-crossings (block centers)
    for (r, c, color) in found_blocks:
        output[r][c] = color

    # Set inter-crossings to 0
    for i in range(len(found_blocks)):
        (r_i, c_i, color_i) = found_blocks[i]
        for j in range(i+1, len(found_blocks)):
            (r_j, c_j, color_j) = found_blocks[j]
            output[r_i][c_j] = 0
            output[r_j][c_i] = 0

    # Add isolated cells (only if output position is still 0)
    isolated = {}
    for r in range(rows):
        for c in range(cols):
            if (r, c) not in block_cells:
                isolated[(r, c)] = grid[r][c]

    for (r, c), val in isolated.items():
        if output[r][c] == 0:
            output[r][c] = val

